package com.careerguidance.controller;
import com.careerguidance.dto.request.*; import com.careerguidance.dto.response.*; import com.careerguidance.service.MentorVerificationService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api") public class MentorVerificationController {
 private final MentorVerificationService service; private final Path uploadRoot=Paths.get("uploads","mentor-documents"); public MentorVerificationController(MentorVerificationService s){service=s;}
 @PostMapping("/auth/register/mentor") public ResponseEntity<MessageResponse> register(@Valid @RequestBody MentorRegistrationRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(r));}
 @PostMapping(value="/auth/mentor-documents",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,String> upload(@RequestParam("file") MultipartFile file) throws IOException {if(file.isEmpty()||file.getSize()>10*1024*1024)throw new IllegalArgumentException("File must be no more than 10 MB");String type=Optional.ofNullable(file.getContentType()).orElse("");String name=Optional.ofNullable(file.getOriginalFilename()).orElse("").toLowerCase();if(!(type.equals("application/pdf")||type.equals("image/jpeg")||type.equals("image/png")||name.endsWith(".pdf")||name.endsWith(".jpg")||name.endsWith(".jpeg")||name.endsWith(".png")))throw new IllegalArgumentException("Only PDF, JPG and PNG files are allowed");Files.createDirectories(uploadRoot);String safe=UUID.randomUUID()+name.substring(name.lastIndexOf('.'));Files.copy(file.getInputStream(),uploadRoot.resolve(safe));return Map.of("fileUrl","/uploads/mentor-documents/"+safe);}
}
